21	// ✅ CORRECT: Offload blocking work to a dedicated thread pool
22	async fn good_handler() -> String {
23	    let data = tokio::task::spawn_blocking(|| {
24	        std::fs::read_to_string("big_file.txt").unwrap()
25	    }).await.unwrap();
26	    process(&data)
27	}
28	
29	// ✅ ALSO CORRECT: Use tokio's async fs
30	async fn also_good_handler() -> String {
31	    let data = tokio::fs::read_to_string("big_file.txt").await.unwrap();
32	    process(&data)
33	}
